def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The three-cell vertical pattern is shown at the right edge.
    pattern = [grid[1][w - 1], grid[2][w - 1], grid[3][w - 1]]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                for k, color in enumerate(pattern):
                    rr = r + k - 1
                    if 0 <= rr < h:
                        out[rr][c] = color
    return out
